def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep = next(c for c in range(w) if all(g[r][c] == 2 for r in range(h)))
    bg = g[0][sep + 1]
    # Locate each source object's bounding box by color.
    boxes = {}
    for color in set(grid[0][sep+1:]):
        pts = [(r,c) for r in range(h) for c in range(sep) if grid[r][c] == color]
        if pts:
            boxes[color] = (min(r for r,c in pts), max(r for r,c in pts), min(c for r,c in pts), max(c for r,c in pts))
    for color, (r0,r1,c0,c1) in boxes.items():
        dest_rows = [r for r in range(1,h-1) if grid[r][sep+1] == color]
        dest_cols = [c for c in range(sep+1,w-1) if grid[0][c] == color]
        if not dest_rows:
            continue
        # Only objects represented in the output frame are erased.
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if g[r][c] == color:
                    g[r][c] = 0
        dr, dc = (r1-r0)//2, (c1-c0)//2
        for rr in dest_rows:
            for cc in dest_cols:
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1):
                        if grid[r][c] == color:
                            g[rr+r-r0-dr][cc+c-c0-dc] = color
    return g

